std::vector<f32> UnpackWeights() {
    std::vector<f32> out(kTotalFloatCount);
    for (std::size_t i = 0; i < kTotalFloatCount; ++i) {
        out[i] = HalfToFloat(kPackedWeights[i]);
    }
    return out;
}

